def esc(s):return html.escape(str(s))
def fmt(v,digits=2):return '—' if v is None else f'{v:.{digits}f}'
def table(head,rows,ident=''):
    return '<div class="scroll"><table id="'+ident+'"><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def main():
    p=argparse.ArgumentParser();p.add_argument('campaign',type=Path);p.add_argument('output',type=Path);a=p.parse_args();r=a.campaign.resolve();out=a.output.resolve();out.mkdir(parents=True,exist_ok=True);repo=Path(__file__).resolve().parents[1]
    audit=json.loads((r/'scaling-audit.json').read_text());progress=json.loads((r/'scale-progress.json').read_text());telemetry=json.loads((out/'telemetry-summary.json').read_text());baseline=json.loads((repo/'reports/five-node-20261113/analysis.json').read_text())
    sci=audit['jobs'].get(progress['scientific_job'],{});inf=audit['jobs'].get(progress['inference_submission']['job_id'],{});science_hours=int(sci.get('ElapsedRaw',0))/3600
    verified=audit['model_coordinates_independently_checked'] and not audit['errors'];models=audit['verified_models'];crop={m['sha256']:m for m in models if m['kind']=='crop'};intact={m['sha256']:m for m in models if m['kind']=='intact'}
