    inference_latency=sorted(row['seconds'] for row in inference_rows)
    inference_summary=('During the science allocation, the owned relay recorded '+str(len(inference_rows))+' completion requests; status counts: '+str(dict(Counter(row['status'] for row in inference_rows)))+'. Median latency '+fmt(statistics.median(inference_latency))+' seconds; p90 '+fmt(inference_latency[int(.9*(len(inference_latency)-1))])+' seconds. This includes tournament/control requests, retries and readiness probes, not just scientific code generation.' if inference_rows else '')
    role_times=defaultdict(list)
    for entry in audit['agent_timings']:role_times[entry['role']].append(entry)
    agent_table=table(['Agent role','Finished attempts','Attempts with errors','Median wall seconds','P90 wall seconds','Median model requests on successful attempts'],[[role,len(entries),sum(bool(x['error_type']) for x in entries),fmt(statistics.median(x['seconds'] for x in entries)),fmt(sorted(x['seconds'] for x in entries)[int(.9*(len(entries)-1))]),fmt(statistics.median(x['requests'] for x in entries if x.get('requests') is not None),0) if any(x.get('requests') is not None for x in entries) else 'not recorded'] for role,entries in role_times.items()])
    comparison=table(['Metric','Previous five-node phase','Current continuation'],[['Scientific GPU slots',20,76 if sci.get('start_epoch') else '76 requested; queued'],['Local inference GPU slots','External inference; not allocated in the five-node job',4],['Mean leased science GPU-slot occupancy','18.32%',fmt(100*telemetry.get('science_slot_leases',{}).get('mean_leased_slot_fraction',0))+'%'],['Peak leased science GPU slots',18,telemetry.get('science_slot_leases',{}).get('peak_leased_slots','not reconstructed')],['Reviewed hypothesis-round evaluations',15,sum(v['reviewed'] for v in audit['rounds'].values())],['Distinct represented crop binder sequences',43,len(catalog)],['Verified unique crop complex files',215,len(crop) if verified else 'not independently checked'],['Verified crop models / science-allocation hour','208.06',fmt(throughput)],['Crop models / allocated GPU-hour','10.40 (science job only)',fmt(cost_rate)+' (science + local inference, including allocated warmup/idle)']])
    node_stats=table(['Observed node','Role','Samples','Covered minute bins','Mean sampled GPU busy %','P95 GPU busy %','Mean sampled CPU busy %'],[[h,d['kind'],d['samples'],f'{100*d["covered_minute_fraction"]:.1f}%',fmt(d['mean_sampled_GPU_busy_percent']),fmt(d['p95_sampled_GPU_busy_percent']),fmt(d.get('mean_sampled_CPU_busy_percent'))] for h,d in telemetry['nodes'].items()])
    downloads='<a href="candidate-metrics.csv">Candidate CSV</a> · <a href="designed-binders.fasta">Designed sequences</a>' if catalog else 'No main-campaign candidate artifacts yet.'
